import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong(), q = (int) nextLong();
        long[] p = new long[n], prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            p[i] = nextLong();
            prefix[i + 1] = prefix[i] + p[i];
        }
        // end[j]: one past the last car sharing car j's position, so equal positions refuel together.
        int[] end = new int[n];
        for (int j = 0; j < n; j++) end[j] = j + 1;
        for (int j = n - 2; j >= 0; j--)
            if (p[j] == p[j + 1]) end[j] = end[j + 1];
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            long a = end[(int) nextLong() - 1], b = end[(int) nextLong() - 1];
            // Cars [0,a) stop at station a, [a,b) at station b, [b,n) at the last car.
            long total = a * p[(int) a - 1] + (b - a) * p[(int) b - 1] + (n - b) * p[n - 1] - prefix[n];
            if (i > 0) sb.append(' ');
            sb.append(total);
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n, q := int(nextInt()), int(nextInt())
	p, prefix := make([]int64, n), make([]int64, n+1)
	for i := range p {
		p[i] = nextInt()
		prefix[i+1] = prefix[i] + p[i]
	}
	// end[j]: one past the last car sharing car j's position, so equal positions refuel together.
	end := make([]int64, n)
	for j := range end {
		end[j] = int64(j + 1)
	}
	for j := n - 2; j >= 0; j-- {
		if p[j] == p[j+1] {
			end[j] = end[j+1]
		}
	}
	w := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer w.Flush()
	for i := 0; i < q; i++ {
		a, b := end[nextInt()-1], end[nextInt()-1]
		// Cars [0,a) stop at station a, [a,b) at station b, [b,n) at the last car.
		total := a*p[a-1] + (b-a)*p[b-1] + (int64(n)-b)*p[n-1] - prefix[n]
		if i > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.FormatInt(total, 10))
	}
	w.WriteByte('\n')
}
